export const STR = { en, tr, ar };
export const LABELS = LBL;

// t(key, vars): dictionary lookup with English fallback and {placeholder} substitution
export function T(lang) {
  const d = STR[lang] || en;
  return (key, vars) => { let s = d[key] ?? en[key] ?? key; if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v)); return s; };
}
export function labels(lang) {
  const base = LBL.en; const d = LBL[lang] || {};
  return Object.fromEntries(Object.entries(base).map(([k, v]) => [k, { ...v, ...(d[k] || {}) }]));
}
// '/desk/x/' -> '/desk/tr/x/' for the given language; non-Desk paths are returned unchanged
export function localize(path, lang) {
  const m = String(path).match(/^\/desk\/(?:(?:tr|ar)\/)?(.*)$/);
  if (!m) return path;
  return '/desk/' + (lang && lang !== 'en' ? lang + '/' : '') + m[1];
}
